/* eslint-disable react/no-array-index-key */
/* eslint-disable no-nested-ternary */
import React, { useEffect, useMemo, useState } from 'react';
import {
  CopyOutlined,
  FileTextOutlined,
  UnorderedListOutlined,
  WarningOutlined,
  LeftOutlined
} from '@ant-design/icons';
import { Button, Collapse, message, Tooltip } from 'antd';
import ReactLoader from 'components/common/reactLoading';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import styled from 'styled-components';
import {
  useSessionHeader,
  useSessionTimeLine,
} from 'components/shared/Sessions/Context';
import { useAnrSession } from 'components/features/sessions/hooks/useSessionDetail';
import { useSelector } from 'react-redux';

const { Panel } = Collapse;
const ButtonGroup = Button.Group;
const BackToReplayBtn = styled.div`
  display: inline-block;
  margin: 0px 0px 0px 15px;
  .ant-btn{
    border-radius: 4px;
    border: 1px solid rgba(165, 165, 165, 0.4);
    color: #5D97FF;
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    height: 30px;
    line-height: 30px;
    padding: 0px 10px;
  }
`
const StackTraceBoxWrapper = styled.div`
  position: relative;
  height: 100%;
  .ant-collapse{
    padding-left: 15px;
    padding-right: 15px;
  }
`

const AnrTrace = () => {
  const [buttonClick, setButtonClick] = useState('list');

  const { urlReducer: urlQuery } = useSelector(state => state);
  const { shareSessionKey, appId: urlAppId, sessionid } = urlQuery;
  const { sessionDetail } = useSessionTimeLine();
  const { selectedHeaderField: selectedField, setSelectedHeaderField } = useSessionHeader();
  const { _id: sessionId, appId, platform } = sessionDetail;

  const reqBody = useMemo(
    () => ({
      ...(!shareSessionKey && {
        appid: urlAppId || appId,
        sessionid: sessionid || sessionId,
        anr_number: selectedField?.split('_')[1],
      }),
      ...(shareSessionKey && { 
        anr_number: selectedField?.split('_')[1],
        shareSessionKey } )
    }),
    [urlAppId, appId, sessionid, sessionId, selectedField, shareSessionKey]
  );
  const urlPath = shareSessionKey ? '/uifreezes/public/ui_freeze_logs' : '/uifreezes/ui_freeze_logs';
  const {
    isLoading: isDataLoading,
    isFetching,
    data: anrSessionData,
    refetch: refetchAnrInfo,
  } = useAnrSession(urlPath, reqBody);
  const anrData = anrSessionData?.data?.data;

  const handleButtonClick = (value) => {
    setButtonClick(value);
  };

  useEffect(() => {
    refetchAnrInfo();
    return () => {
      setButtonClick('list');
    };
  }, [sessionId, selectedField]);

  const crashLogText = useMemo(() => {
    const newCrashLogText = [];
    const exceptionValue = anrData?.exceptions;
    const threadValue = anrData?.threads;
    if (exceptionValue instanceof Array) {
      exceptionValue.map((obj) => {
        newCrashLogText.push(
          `\n ${obj.name} : ${obj.method_name} :  ${obj.reason}`
        );
        typeof obj?.callstack === 'object' && obj?.callstack?.map((value) =>
            newCrashLogText.push(
              platform === 1
                ? `\n \t at ${''}${value} `
                : `\n \t ${value}`
            )
          );
      });
    }

    if (threadValue instanceof Array) {
      threadValue.map((obj) => {
        newCrashLogText.push(`\n ${obj.name}: ${obj.method_name}`);
        if (obj.backtrace) {
          obj.backtrace.map((value) =>
            newCrashLogText.push(
              platform === 1
                ? `\n \t at ${''}${value} `
                : `\n \t ${value}`
            )
          );
        }
        if (obj.properties) {
          newCrashLogText.push(`\n with additional properties`);
          Object.keys(obj.properties).map((key) => {
            newCrashLogText.push(`\n \t \t \t ${key} : ${obj.properties[key]}`);
          });
        }
      });
    }
    return newCrashLogText;
  }, [anrData]);

  return (
    <StackTraceBoxWrapper>
      <div className="stack-trace-box">
      <BackToReplayBtn>
        <Button onClick={() => setSelectedHeaderField('sessionVideo')}><LeftOutlined/> Back to replay</Button>
      </BackToReplayBtn>
        {anrData ? (
          <div>
            <div className="anr-copy-bar">
              <div className="button-group">
                <ButtonGroup>
                  <Tooltip title="List view">
                    <Button
                      icon={<UnorderedListOutlined />}
                      onClick={() => handleButtonClick('list')}
                      type={buttonClick === 'list' ? 'active' : ''}
                      className="btn-list-view"
                    />
                  </Tooltip>
                  <Tooltip title="Text view">
                    <Button
                      icon={<FileTextOutlined />}
                      onClick={() => handleButtonClick('text')}
                      type={buttonClick === 'text' ? 'active' : ''}
                      className="btn-text-view"
                    />{' '}
                  </Tooltip>
                  <CopyToClipboard onCopy={() => {}} text={crashLogText}>
                    <Tooltip title="Copy UI Freeze log">
                      <Button
                        icon={<CopyOutlined />}
                        onClick={() =>
                          message.success(
                            'Log message for the UI Freeze has been copied to clipboard.'
                          )
                        }
                        className="btn-copy"
                      />
                    </Tooltip>
                  </CopyToClipboard>
                </ButtonGroup>
              </div>
            </div>
            <Collapse
              defaultActiveKey={['0']}
              expandIconPosition="right"
              className={
                buttonClick === 'text'
                  ? 'custom-scrollbar crashlog-textview'
                  : 'custom-scrollbar'
              }
            >
              {anrData?.threads instanceof Array &&
                anrData?.threads.map((obj, index) => (
                  <Panel
                    header={<span className="panel-title">{obj.name}</span>}
                    key={index}
                    disabled
                    extra={obj.method_name}
                    showArrow={false}
                  >
                    {buttonClick === 'text' && (
                      <ul className="title" key="ab01">
                        <li>{`${obj.name}:${''} ${obj.method_name}`}</li>
                      </ul>
                    )}
                    <ul className="threads">
                      {obj.backtrace &&
                        obj.backtrace.map((value, traceindex) => (
                          <li key={traceindex}>
                            {buttonClick === 'text' && platform === 1
                              ? `at${' '} ${value}`
                              : value}
                          </li>
                        ))}
                    </ul>
                  </Panel>
                ))}
            </Collapse>
          </div>
        ) : isDataLoading || isFetching || typeof anrData?.message !== 'string' ? (
          <ReactLoader className='react-loader' />
        ) : (
          <div
            style={{ alignItems: 'center', height: '70px', width: '220px' }}
            className="no-data-msg-box"
          >
            <WarningOutlined style={{ marginRight: '10px' }} />
            {`To see a full stack trace of the ANR please upgrade your SDK to version ${
              platform === 1 ? '3.3.0' : '3.2.4'
            } or higher.`}
          </div>
        )}
      </div>
    </StackTraceBoxWrapper>
  );
};
export default AnrTrace;
