const BugTrace = () => {
  const [buttonClick, setButtonClick] = useState('list');

  const { selectedHeaderField: selectedField, setSelectedHeaderField } = useSessionHeader();
  const { sessionDetail, sessionBugInfo: bugDetails } = useSessionTimeLine();
  const { urlReducer: urlQuery } = useSelector(state => state);
  const { shareSessionKey, appId: urlAppId, sessionid, starttime } = urlQuery;
  const { _id: sessionId, appId, platform } = sessionDetail;

  const bugExceptionKey = selectedField?.substring(10, selectedField?.indexOf('+'));
  const bugInfo = useMemo(() => bugDetails?.find(bug => bug?.timeFromStart?.toString() === bugExceptionKey), [bugExceptionKey]);
  const urlPath = shareSessionKey ? '/exceptions/public/exception_logs' : '/exceptions/exception_logs';

  const reqExceptionBody = useMemo(() => ({
    ...(!shareSessionKey && {
      appid: urlAppId || appId,
      sessionid: sessionid || sessionId,
      time_from_start: bugInfo?.timeFromStart || starttime}),
    ...(shareSessionKey && { 
      time_from_start: bugInfo?.timeFromStart || starttime,
      shareSessionKey })
  }), [urlAppId, appId, sessionid, sessionId, starttime, bugInfo?.timeFromStart, shareSessionKey]);
  const { isLoading: isDataLoading, data: bugData, refetch: refetchExceptionInfo } = useExceptionsSession(urlPath, reqExceptionBody)
  const exception = bugData?.data?.data;
  const crashLogText = useMemo(() => {
    const newCrashLogText = [];
    const exceptionValue = exception?.exceptions;
    const threadValue = exception?.threads;
    if (exceptionValue instanceof Array) {
      exceptionValue.map((obj) => {
        newCrashLogText.push(
          `\n ${obj.name} : ${obj.method_name} :  ${obj.reason}`
        );
          typeof obj?.callstack === 'object' && obj?.callstack?.map((value) =>
            newCrashLogText.push(
              platform === 1
                ? `\n \t at ${''}${value} `
                : `\n \t ${value}`
            )
          );
      });
    }

    if (threadValue instanceof Array) {
      threadValue.map((obj) => {
        newCrashLogText.push(`\n ${obj.name}: ${obj.method_name}`);
        if (obj.backtrace && obj.backtrace instanceof Array) {
          obj.backtrace.map((value) =>
            newCrashLogText.push(
              platform === 1
                ? `\n \t at ${''}${value} `
                : `\n \t ${value}`
            )
          );
        }
        if (obj.properties) {
          newCrashLogText.push(`\n with additional properties`);
          Object.keys(obj.properties).map((key) => {
            newCrashLogText.push(`\n \t \t \t ${key} : ${obj.properties[key]}`);
          });
        }
      });
    }
    return newCrashLogText;
  }, [exception]);

  const exceptionHeader = (name, method) => (
    <div className="exception-title">
      <h4>{`${name}`}</h4>
      <p>{`${method}`}</p>
    </div>
  );

  const handleButtonClick = (value) => {
    setButtonClick(value);
  };

  useEffect(() => {
    refetchExceptionInfo();
    return () => {
      setButtonClick('list');
    };
  }, [selectedField]);

  return (
    <StackTraceBoxWrapper>
      <div className="stack-trace-box">
        <BackToReplayBtn>
          <Button onClick={() => setSelectedHeaderField('sessionVideo')}>
            <LeftOutlined /> Back to replay
          </Button>
        </BackToReplayBtn>
        {!isDataLoading && exception && !isEmpty(exception) ? (
          <div>
            <div className="bug-copy-bar">
              <div className="button-group">
                <ButtonGroup>
                  <Tooltip title="List view">
                    <Button
                      icon={<UnorderedListOutlined />}
                      onClick={() => handleButtonClick('list')}
                      type={buttonClick === 'list' ? 'active' : ''}
                      className="btn-list-view"
                    />
                  </Tooltip>
                  <Tooltip title="Text view">
                    <Button
                      icon={<FileTextOutlined />}
                      onClick={() => handleButtonClick('text')}
                      type={buttonClick === 'text' ? 'active' : ''}
                      className="btn-text-view"
                    />{' '}
                  </Tooltip>
                  <Tooltip title="Copy Exception log">
                    <Button
                      icon={<CopyOutlined />}
                      onClick={() => {
                        navigator.clipboard.writeText(crashLogText);
                        message.success(
                          'Log message for the Exception has been copied to clipboard.'
                        );
                      }}
                      className="btn-copy"
                    />
                  </Tooltip>
                </ButtonGroup>
              </div>
            </div>
            {exception &&
              exception.threads instanceof Array &&
              exception.threads.map((obj) => (
                <Tabs
                  defaultActiveKey="1"
                  className="bugtrace-tab"
                  animated={false}
                >
                  <TabPane tab="Stacktrace" key="1">
                    <Collapse
                      defaultActiveKey={['1']}
                      className="custom-scrollbar"
                      expandIconPosition="right"
                    >
                      <Panel
                        header={exceptionHeader(obj.name, obj.reason)}
                        key="1"
                        disabled
                        extra={obj.method_name}
                        showArrow={false}
                      >
                        {buttonClick === 'text' && (
                          <ul key="ab01" className="title">
                            <li>{`${obj.name}:${' '} ${obj.reason}:${' '} ${
                              obj.method_name
                            }`}</li>{' '}
                          </ul>
                        )}
                        <ul className="threads">
                          {(obj.backtrace && obj.backtrace instanceof Array) ?
                            obj.backtrace.map((value, threadIndex) => (
                              <li key={threadIndex}>
                                {buttonClick === 'text' && platform === 1
                                  ? `at${' '} ${value}`
                                  : value}
                              </li>
                            )): (
                              <li key={obj.backtrace || 1}>
                                {obj.backtrace || ''}
                              </li>
                          )}
                        </ul>
                      </Panel>
                    </Collapse>
                  </TabPane>
                  {!isEmpty(obj.properties) && (
                    <TabPane tab="Properties" key="2">
                      <div className="properties-wrapper">
                        <div className="properties-head">
                          <div className="properties-name">Property</div>{' '}
                          <div className="properties-value">Value</div>
                        </div>
                        <div className="properties-content">
                          {obj.properties &&
                            Object.keys(obj.properties).map((key) => (
                              <div className="content" key={key}>
                                <div className="key">{`${key}`}</div>
                                <div className="property">
                                  {`${obj.properties[key]}`}
                                  <CopyToClipboard
                                    onCopy={() => {}}
                                    text={`${obj.properties[key]}`}
                                  >
                                    <CopyOutlined
                                      onClick={() => message.success('Copied')}
                                    />
                                  </CopyToClipboard>
                                </div>
                              </div>
                            ))}
                        </div>
                      </div>
                    </TabPane>
                  )}
                </Tabs>
              ))}
          </div>
        ) : exception && exception.length === 0 && !isDataLoading ? (
          <div
            style={{ alignItems: 'center', height: '70px', width: '220px' }}
            className="no-data-msg-box"
          >
            <WarningOutlined type="warning" style={{ marginRight: '10px' }} />
            {`To see a full stack trace of the exception please upgrade your SDK to version ${
              platform === 1 ? '3.3.0' : '3.2.4'
            } or higher.`}
          </div>
        ) : isDataLoading ? (
          <ReactLoader className="react-loader" />
        ) : (
          ''
        )}
      </div>
    </StackTraceBoxWrapper>
  );
};

export default BugTrace;
